catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    var available_room = g_form.getValue('requested_room');
    var room_arr = available_room.split(",");
    var final_str = "";
    if (isLoading || newValue == '') {
        return;
    }
    if (newValue != '') {
        var ga = new GlideAjax('OWS_Availability');
        ga.addParam('sysparm_name', 'getAnswer');
        ga.addParam('sysparm_evStart', g_form.getValue('event_start_date'));
        ga.addParam('sysparm_evEnd', g_form.getValue('event_end_date'));
        ga.addParam('sysparm_evSpace', g_form.getValue('requested_room'));
        ga.getXML(spaceAvailable);
    }

function spaceAvailable(response) {
    var answer = response.responseXML.documentElement.getAttribute("answer");

    if (!answer) {
        console.error("No answer received from server-side GlideAjax call.");
        return;
    }

    var answer_obj;
    try {
        answer_obj = JSON.parse(answer);
    } catch (e) {
        console.error("Failed to parse answer: ", answer);
        return;
    }

    if (!Array.isArray(answer_obj)) {
        console.error("Parsed answer is not an array:", answer_obj);
        return;
    }

    for (var i = 0; i < answer_obj.length; i++) {
        if (answer_obj[i].is_available === false) {
            final_str = answer_obj[i].name;
            var index = room_arr.indexOf(answer_obj[i].sys_id);
            if (index !== -1) {
                room_arr.splice(index, 1);
            }
        }
    }

    if (final_str) {
        alert(final_str + " is not available. Please select a different room.");
    }

    g_form.setValue('requested_room', room_arr.toString());
}


}
